INSERT INTO feature VALUES('cell-occurrence-count','quantities','Each hole''s occurrence count','cell-rewriting','implemented','notable',NULL,'`gandr cells` reports every cell a source''s declarations elaborate to, each hole with how many times the cell''s right side writes it, its Lipschitz constant under the step: zero for a dropped hole, more than one for a copied one; a cell''s growth carries its largest count. The count is reported, never refused: a copy on the left side is refused at admission. `gandr cells --fusions` also fuses each composition overlap of a block, composes the fused cell''s bound through its two steps in the Lawvere quantale, one tick for each written rule and each hole''s count scaled through the holes it passes, and reports the bound with its verdict against the fused cell''s own counts.','theory-cell-complexes surface-dispatcher surface-driver','corpus/model/desc/occurrence-count.gandr corpus/pathological/desc/occurrence-count.gandr crates/surface-dispatcher/src/cells.rs crates/surface-dispatcher/tests/distances.rs crates/surface-driver/tests/cli.rs','corpus/model/desc/occurrence-count.gandr','#2788');
